def reverse_delete(s, c):
    """Remove characters in s that are present in c and check if the result is a palindrome."""
    chars_to_remove = set(c)
    filtered = ''.join([ch for ch in s if ch not in chars_to_remove])
    is_palindrome = filtered == filtered[::-1]
    return (filtered, is_palindrome)

